def card(task, wd):

    def pages_of(words, combine=1.2, pause=0.15, cap=6):
        pages = []
        for w, a, b in words:
            if pages and a - pages[-1]['end'] <= pause and (b - pages[-1]['start'] <= combine) and (len(pages[-1]['words']) < cap):
                pages[-1]['words'].append(w)
                pages[-1]['end'] = b
            else:
                pages.append({'words': [w], 'start': a, 'end': b})
        return pages
    pg = pages_of(WORDS)
    out = jdump(Path(wd) / 'pages.json', pg)
    overlap = any((p['end'] > q['start'] for p, q in zip(pg, pg[1:])))
    return ([check('every page spans <= 1.2 s', all((p['end'] - p['start'] <= 1.2 + 1e-09 for p in pg)), [round(p['end'] - p['start'], 2) for p in pg], '<= 1.2'), check('the 0.6 s pause starts a new page', any((p['start'] == 2.8 for p in pg)), [p['start'] for p in pg], '2.8 starts'), check('one page at a time (no overlaps), all 8 words kept', not overlap and sum((len(p['words']) for p in pg)) == 8, len(pg), 'no overlap'), check('negative control: without grouping every word is its own page', len(pages_of(WORDS, combine=0)) == 8 and len(pg) < 8, len(pg), '< 8')], [out])

def card(task, wd):

    def tone_of(text):
        toks = re.findall('[\\w\u0600-ۿ]+|!', text)
        score = {t: sum((tok in v['words'] for tok in toks)) for t, v in TONES.items()}
        return (max(score, key=score.get), score)

    def style(t):
        v = TONES[t]
        return {'tone': t, 'weight': v['weight'][1] if t == 'hype' else v['weight'][0], 'size': sum(v['size']) // 2, 'entrance': v['entrance']}
    samples = {'hype': 'هذا مذهل ! اشترك الآن قبل الانفجار !', 'corporate': 'نتائج الشركة في الربع الثالث تظهر نمو العملاء', 'tutorial': 'افتح الإعدادات ثم اضغط على خطوة الحفظ', 'story': 'كان يا ما كان في قديم الزمان حكاية قديما ذات يوم'}
    got = {k: tone_of(v)[0] for k, v in samples.items()}
    styles = {k: style(v) for k, v in got.items()}
    default = {'weight': 700, 'size': 64}
    mismatch = sum((not (TONES[k]['weight'][0] <= default['weight'] <= TONES[k]['weight'][1] and TONES[k]['size'][0] <= default['size'] <= TONES[k]['size'][1]) for k in samples))
    rep = jw(wd / 'tone_styles.json', styles)
    return ([check('tone detected from each transcript', got == {k: k for k in samples}, got, 'each to itself'), check('hype -> 800-900 weight, 72-96 px, scale-pop', 800 <= styles['hype']['weight'] <= 900 and 72 <= styles['hype']['size'] <= 96, styles['hype'], '900, 84'), check('story -> 400-500 weight, 44-56 px, slow fade', 400 <= styles['story']['weight'] <= 500 and 44 <= styles['story']['size'] <= 56 and ('slow fade' in styles['story']['entrance']), styles['story'], '400, 50'), check('negative control: one default style misfits 3 of 4 tones', mismatch >= 3, mismatch, '>= 3')], [rep])
